import{_ as i,o as n,c as t,a2 as a}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1792978100000}'),o={name:"reference/changelog.md"};function r(s,e,l,d,h,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to MeetCue. Versions follow <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h2 id="_0-2-0-—-2026-10-26" tabindex="-1">0.2.0 — 2026-10-26 <a class="header-anchor" href="#_0-2-0-—-2026-10-26" aria-label="Permalink to &quot;0.2.0 — 2026-10-26&quot;">​</a></h2><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Providers and models are entered freely, the same way in setup and in <strong>Settings › Providers &amp; cost</strong>: choose a provider and type any model name for each task. The names a provider reports appear as suggestions; MeetCue no longer lists models or prices, and links to each provider&#39;s official pricing page instead.</li><li>Anthropic can be reached through a gateway or proxy: enter its base URL next to the key. Base URLs are now stored per provider in <code>providers.baseUrls</code>; an existing OpenAI-compatible base URL is kept.</li><li>Prices for budget tracking are entered under <strong>Settings › Providers &amp; cost › Budget › Your own prices</strong>.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Opening <strong>Run setup again</strong>, the activity log or any other window from a button froze MeetCue on Windows: no window could be moved and the app couldn&#39;t be quit.</li><li>Speech recognition: <ul><li>System sound recognition stopped about 20 seconds into a meeting when nothing was playing yet, showing <code>MC-ASR-002</code>. The connection is now kept alive whether or not audio arrives, and a stream the provider ends is reopened without waiting for sound.</li><li>An unreachable or slow provider held up everything else: stopping or quitting could take up to a minute while MeetCue retried, and audio was dropped meanwhile. Connecting now happens in the background, and every network step has a time limit.</li><li>Error messages now show what went wrong (for example <code>connection timed out</code>), connection errors disappear once recognition is back, and the panel marks a side whose recognition is reconnecting.</li><li>A setting the provider rejects is reported as <code>MC-ASR-004</code> instead of a network problem (<code>MC-ASR-002</code>), and isn&#39;t retried many times a second.</li><li>Connections no longer time out on networks where IPv6 is configured but doesn&#39;t work.</li></ul></li><li>The panel&#39;s level meters stayed flat until a session started, so the microphone looked dead in the panel while it worked in <strong>Settings › Audio</strong>. The visible panel now shows both levels before you press <strong>Start</strong>; nothing is sent anywhere until you do.</li><li>A microphone that delivers only silence (blocked in Windows privacy settings, or muted) is now reported with <code>MC-AUD-002</code>.</li><li>Unexpected errors inside MeetCue are now written to the log.</li></ul><h2 id="_0-1-3-—-2026-10-24" tabindex="-1">0.1.3 — 2026-10-24 <a class="header-anchor" href="#_0-1-3-—-2026-10-24" aria-label="Permalink to &quot;0.1.3 — 2026-10-24&quot;">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are read live from Anthropic&#39;s, Soniox&#39;s and Deepgram&#39;s official pricing pages, and from OpenAI-compatible servers that list prices with their models. Every current Claude model now shows its price and estimated cost; only a model with no price anywhere links to the pricing page.</li><li>Deepgram shows the rate billed today, including limited-time promotions, with the regular rate in the tooltip.</li><li>Changing a model, key, language or hint setting during a meeting takes effect right away: the next question uses the new models, and recognition switches without losing the sentence in progress.</li><li>Every setting can now be changed in the app: sliders for the voice threshold and end-of-sentence silence (now up to 3 s), panel layout and <strong>Reset panel position</strong> in <strong>General</strong>, <strong>Run setup again</strong>, all cost estimate assumptions, a list of your own prices with <strong>Remove</strong>, and the filler words counted in practice reviews. A new microphone or voice threshold also applies during a meeting.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Settings › Diagnostics › Activity log</strong> shows what MeetCue is doing as it happens: starting and pausing, whether audio arrives from each side, recognised sentences, questions and errors. Also in the tray menu, and from any error message.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Clicking <strong>Start</strong> or <strong>Resume</strong> when something was missing (a key, a model, the audio device) did nothing; the reason is now shown, and a session whose audio fails to start is no longer left half running.</li><li>Notices such as a shortcut that&#39;s already taken were never shown.</li><li>The meeting clock kept counting while paused.</li><li>The settings tab list scrolled away on long pages.</li><li>Speech recognition: <ul><li>The first sound of a sentence was often cut off; the 0.3 s before speech is now sent with it.</li><li>Recognition stopped for the rest of the meeting after a second connection drop, and after pausing for more than a few seconds; it now keeps the connection alive while paused and reconnects whenever needed.</li><li>With Deepgram, English sentences lost the spaces between their parts (&quot;yourexperience&quot;).</li><li>With Deepgram and both Chinese and English selected, English was sent to the Mandarin model. The first language in <strong>Meeting languages</strong> is now the main one, and there is a &quot;Mostly English, some Chinese&quot; choice.</li><li>The end-of-sentence silence setting was cut short at 0.8 s.</li></ul></li></ul><h2 id="_0-1-2-—-2026-10-24" tabindex="-1">0.1.2 — 2026-10-24 <a class="header-anchor" href="#_0-1-2-—-2026-10-24" aria-label="Permalink to &quot;0.1.2 — 2026-10-24&quot;">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Prices are no longer built into the app. MeetCue downloads the <a href="/meetcue/reference/pricing">price reference</a>, checked against each provider&#39;s official pricing page, keeps the last copy for offline use, and can update it from <strong>Settings › Providers &amp; cost</strong>.</li><li>A more compact <strong>Models &amp; prices</strong> layout: one line per model with its price and estimated cost per hour, sorted by cost, with <strong>Cheapest</strong> and <strong>Fastest</strong> marked. API keys take one row per provider.</li><li>A model without a published price links to the provider&#39;s official pricing page instead of showing <strong>Price unknown</strong>.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram Nova-3 used the multilingual rate. MeetCue requests one language for Chinese or English, which costs $0.0077 per minute.</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Prices for Claude Sonnet 5, Claude Opus 5 and Claude Fable 5.1.</li></ul><h2 id="_0-1-1-—-2026-10-24" tabindex="-1">0.1.1 — 2026-10-24 <a class="header-anchor" href="#_0-1-1-—-2026-10-24" aria-label="Permalink to &quot;0.1.1 — 2026-10-24&quot;">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Deepgram, Anthropic and OpenAI-compatible keys failed verification and sessions using them would not start: only Soniox was wired up.</li><li>The setup window turned blank instead of closing when you clicked <strong>Finish</strong>.</li><li>Switches in Settings were drawn with the knob off-centre.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Amazon Bedrock. Use Anthropic or an OpenAI-compatible API for hints.</li></ul><h2 id="_0-1-0-—-2026-10-23" tabindex="-1">0.1.0 — 2026-10-23 <a class="header-anchor" href="#_0-1-0-—-2026-10-23" aria-label="Permalink to &quot;0.1.0 — 2026-10-23&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Meeting mode: live question detection with early trigger, numbered talking points in about a second and a half, a question queue, and coverage ticks.</li><li>Floating panel that doesn&#39;t take focus, with full and mini layouts, click-through and hiding from screen sharing.</li><li>Speech recognition with Soniox and Deepgram; hints with Anthropic, Amazon Bedrock and OpenAI-compatible APIs.</li><li>Latency probe with endpoint selection, cost estimates and combination ranking.</li><li>Price table, usage tracking, budgets and CSV export.</li><li>Practice mode: subtitle and question-list import with preview editing, questions read aloud with system voices, real or simulated recognition, follow-up questions, four hint levels, and a review report with Markdown export.</li><li>Briefing material from txt, md, docx and pdf files.</li><li>English and Simplified Chinese interface and documentation.</li><li>Error codes with linked fixes, diagnostics export, <code>--demo</code> and <code>--self-test</code>.</li></ul>',30)])])}const p=i(o,[["render",r]]);export{u as __pageData,p as default};
